import os
import tomllib
from typing import Any, Mapping, Optional


class EnvCfgError(Exception):
    """Raised when environment configuration is invalid."""
    pass


def _coerce(value: str, expected_type: type) -> Any:
    """Coerce a string to the expected type, raising EnvCfgError on failure."""
    try:
        if expected_type is int:
            return int(value)
        if expected_type is float:
            return float(value)
        if expected_type is bool:
            lower = value.lower()
            if lower in ("true", "1", "yes"):
                return True
            if lower in ("false", "0", "no"):
                return False
            raise EnvCfgError(f"invalid boolean for key '{value}': got '{value}'")
        if expected_type is str:
            return value
        raise EnvCfgError(f"unknown type {expected_type} for key '{value}'")
    except ValueError:
        raise EnvCfgError(f"invalid {expected_type.__name__} for key '{value}': got '{value}'")


def _load_env(
    defaults: dict, env_prefix: str, env: Optional[Mapping[str, str]] = None
) -> dict:
    """Load environment variables, coercing to match defaults, and collecting errors."""
    errors: list[str] = []
    result = {}
    env = env or os.environ
    prefix_len = len(env_prefix) + 2  # prefix + "__"

    for key, value in env.items():
        if not key.startswith(env_prefix + "__"):
            continue
        path = key[prefix_len:].lower().replace("__", ".")
        if path not in defaults:
            errors.append(f"unknown environment key '{key}'")
            continue
        default = defaults[path]
        try:
            result[path] = _coerce(value, type(default))
        except EnvCfgError as e:
            errors.append(str(e))

    if errors:
        raise EnvCfgError("; ".join(errors))
    return result


